class Solution {
public:
 int minimumIncompatibility(vector<int>& nums, int k) {
  int n=nums.size(), g=n/k, full=(1<<n)-1, INF=1e9;
  vector<int> cost(1<<n,INF);
  for(int mask=0;mask<=full;++mask) if(__builtin_popcount((unsigned)mask)==g){
   unordered_set<int> seen; int lo=INT_MAX,hi=INT_MIN; bool ok=true;
   for(int i=0;i<n;++i) if(mask>>i&1){if(!seen.insert(nums[i]).second){ok=false;break;} lo=min(lo,nums[i]);hi=max(hi,nums[i]);}
   if(ok) cost[mask]=hi-lo;
  }
  vector<int> dp(1<<n,INF);dp[0]=0;
  for(int mask=0;mask<=full;++mask) if(dp[mask]!=INF && __builtin_popcount((unsigned)mask)%g==0 && mask!=full){
   int free=full^mask, first=__builtin_ctz((unsigned)free);
   for(int sub=free;sub;sub=(sub-1)&free) if((sub>>first&1) && cost[sub]!=INF)
    dp[mask|sub]=min(dp[mask|sub],dp[mask]+cost[sub]);
  }
  return dp[full]==INF?-1:dp[full];
 }
};
